{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; INSERT INTO snitch_db.maplemonk.inventory_daily_snapshot ( snapshot_ts, sku_group, category, cut_size, l1_category, original_price, current_slashed_price, online_inventory, offline_inventory, sku_class, shopify_sales, shopify_quantity, shopify_discount, offline_sales, offline_quantity, offline_discount, mp_sales, mp_quantity, mp_discount ) with prod as ( select sku_group, category, CASE WHEN LEFT(sku_group, 4) = \'4MBG\' AND ONLINE_XL3_UNITS >= 5 AND ONLINE_XL4_UNITS >= 5 AND ONLINE_XL5_UNITS >= 2 THEN \'non_cut\' WHEN LEFT(sku_group, 4) <> \'4MBG\' AND ONLINE_S_UNITS >= 5 AND ONLINE_M_UNITS >= 5 AND ONLINE_L_UNITS >= 5 THEN \'non_cut\' ELSE \'cut\' END AS cut_size, l1_category, original_price, current_slashed_price, online_inventory, offline_inventory, final_sku_class as sku_class from snitch_db.maplemonk.base_product where status = \'ACTIVE\' and online_inventory>0 ), shopify_sales_pre as ( select sku_group, case when lower(ifnull(discount_code,\'others\')) like \'%eco%\' or lower(ifnull(discount_code,\'others\')) like \'%influ%\' or lower(ifnull(discount_code,\'others\')) like \'%rms%\' or tags = \'FLITS_LOGICERP\' or lower(ifnull(discount_code,\'others\')) like \'%creator%\' then 1 else 0 end as removing_flag, sum(gross_sales)::int as sales, sum(quantity)::int as quantity, greatest(sum(line_item_sales-gross_sales),0)::int as discount from snitch_db.maplemonk.fact_items_snitch where order_status = \'Shopify_Processed\' and order_timestamp::date = current_date -1 group by 1,2 ), shopify_sales as ( select sku_group, sales, quantity, discount from shopify_sales_pre where removing_flag = 0 ), store_sales_pre as ( select sku_group, case when lower(sku_group) like \'cb%\' or marketplace_mapped in (\'SNITCH - WH - B2B\', \'SNITCH - SNITCH X\', \'SNITCH - WH - M P\', \'SNITCH - WH - SR\', \'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - WH - U.P\', \'SNITCH - WH - NORTH\', \'SNITCH - WH - YELHANKA\', \'SNITCH - WH - YELHANKA\' , \'SNITCH - WH - EMIZA\', \'SNITCH - WH - YELHANKA 2\') or doc_prefix in (\'OMS\',\'QCOM\') then 1 else 0 end as removing_flag, sum(selling_price)::int as sales, sum(suborder_quantity)::int as quantity, sum(abs(discount))::int as discount from snitch_db.maplemonk.store_fact_items_offline WHERE order_date = current_date -1 group by 1,2 ), offline_sales as ( select sku_group, sales, quantity, discount from store_sales_pre where removing_flag = 0 ), mp_sales_pre as ( SELECT sku_group, case when order_name like \'FKSOR%\' then 1 when order_name like \'SLIKK%\' then 1 when order_name like \'KNOT%\' then 1 when order_name like \'ZILO%\' then 1 when order_name like \'SJIT%\' then 1 when order_name like \'MNow%\' then 1 when order_name like \'POGB%\' then 1 when order_name like \'INSTA%\' then 1 else 0 end as filters, sum(shipping_quantity)::int AS quantity, SUM(CASE WHEN LOWER(marketplace_mapped) = \'ajio\' THEN selling_price * 1.45 WHEN LOWER(marketplace_mapped) = \'flipkart\' THEN selling_price + discount ELSE selling_price END ) as sales, abs(SUM(mrp*suborder_quantity) - SUM(CASE WHEN marketplace_mapped = \'AJIO\' THEN (selling_price * 1.5) WHEN LOWER(marketplace_mapped) = \'flipkart\' THEN (selling_price + discount + 150) ELSE selling_price END)) as discount, FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate WHERE TRIM(UPPER(marketPlace_mapped)) IN (\'MYNTRA\', \'NYKAA.COM\', \'NYKAA_FASHION\', \'AMAZON\', \'FLIPKART\',\'AJIO\') AND ADDRESS_LINE_1 != \'FLIPKART_B2B_CUSTOM\' and order_date = current_date - 1 group by 1,2 having sum(shipping_quantity) is not null ), mp_sales as ( select sku_group, sales, quantity, discount from mp_sales_pre where filters = 0 ) select CONVERT_TIMEZONE(\'Asia/Kolkata\', CURRENT_TIMESTAMP()), a.*, ifnull(b.sales,0)::int as shopify_sales, ifnull(b.quantity,0)::int as shopify_quantity, ifnull(b.discount,0)::int as shopify_discount, ifnull(c.sales,0)::int as offline_sales, ifnull(c.quantity,0)::int as offline_quantity, ifnull(c.discount,0)::int as offline_discount, ifnull(d.sales,0)::int as mp_sales, ifnull(d.quantity,0)::int as mp_quantity, ifnull(d.discount,0)::int as mp_discount from prod a left join shopify_sales b on a.sku_group = b.sku_group left join offline_sales c on a.sku_group = c.sku_group left join mp_sales d on a.sku_group = d.sku_group ; CREATE OR REPLACE table snitch_db.maplemonk.inventory_daily_snapshot_latest AS WITH ranked AS ( SELECT *, DATE(CONVERT_TIMEZONE(\'Asia/Kolkata\', snapshot_ts)) AS snapshot_date, ROW_NUMBER() OVER ( PARTITION BY DATE(CONVERT_TIMEZONE(\'Asia/Kolkata\', snapshot_ts)), sku_group ORDER BY snapshot_ts DESC ) AS rn FROM snitch_db.maplemonk.inventory_daily_snapshot ) SELECT * FROM ranked WHERE rn = 1; ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            